import type { CancerInput } from "@/lib/schema";
import type { Spike } from "./index";
import { CX, SRC } from "./lymphoma-treatment-shared";

/**
 * B-CELL LYMPHOMAS OTHER THAN DLBCL: what is given, in what order, in what setting. Facet B of the lymphoma deep
 * spike, 29 September 2026. Primary mediastinal, Burkitt, primary CNS, follicular, marginal zone and MALT, mantle
 * cell and Waldenstrom macroglobulinaemia.
 *
 * Every figure quoted was read from the source abstract through Europe PMC on 29 September 2026, or from a trial or
 * paper record already in the corpus (referenced by id rather than restated). No cancer, trial or target record is
 * created here; the only new ids in this spike are the `lymphoma-tx-*` terms in ./lymphoma-treatment.ts.
 */

const S: Record<string, NonNullable<CancerInput["standardOfCare"]>> = {
  // ------------------------------------------------------------------ PRIMARY MEDIASTINAL B-CELL LYMPHOMA
  pmbcl: [
    { setting: "Primary mediastinal B-cell lymphoma: which first-line regimen, and why radiotherapy is now usually avoided", approach: "A disease of young adults, more often women, presenting with a bulky mass between the lungs that can compress the superior vena cava. It is biologically closer to Hodgkin lymphoma than to diffuse large B-cell lymphoma, which is why PD-1 blockade works in it.\n\nDose-adjusted EPOCH-R for six cycles is the regimen most used in the United States, on the strength of a National Cancer Institute series in which five-year event-free survival was 93 per cent and overall survival 97 per cent, with radiotherapy avoided in 96 per cent of patients. R-CHOP with consolidation radiotherapy is the alternative used in much of Europe. There has never been a randomised comparison of the two.\n\nWhat has been settled is the radiotherapy. IELSG37 randomised patients with a negative end-of-treatment PET to mediastinal radiotherapy or observation: 30-month progression-free survival was 96.2 per cent with observation against 98.5 per cent with radiotherapy, non-inferior, and overall survival was 99 per cent in both arms. Since the patients are young and the field sits over the heart and breasts, avoiding it matters for the next forty years. Radiotherapy is still given where the end-of-treatment PET is positive.", refs: ["paper-dunleavy-da-epoch-r-pmbcl-nejm-2013", "paper-ielsg37-pmbcl-martelli-jco-2024", "r-chop", "rituximab", "etoposide", "doxorubicin", "cyclophosphamide", "vincristine", "prednisone", "fdg-pet", "deauville", "lymphoma-tx-radiotherapy", "lymphoma-tx-hodgkin-late-effects", "lymphoma-tx-fertility-preservation"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO; IELSG37", url: SRC.nciPdqNhl } },
    { setting: "Primary mediastinal B-cell lymphoma that relapses or does not respond", approach: "Relapse is uncommon and almost always early, within the first year. CD19 CAR-T is the treatment of choice and primary mediastinal disease was included in the pivotal ZUMA-1 and TRANSCEND populations. Where CAR-T is not available or has failed, pembrolizumab has an established role: KEYNOTE-170 treated 53 patients whose disease had relapsed after autologous transplant or who could not have one after two or more lines, and reported an objective response of 45 per cent and complete response of 13 per cent, which led to accelerated approval in the United States on 13 June 2018, converted to traditional approval on 14 October 2020. Nivolumab with brentuximab vedotin is the other checkpoint-based option. Salvage chemotherapy with autologous transplant is used where the disease is still chemosensitive and CAR-T is not accessible. Mediastinal radiotherapy is added to a residual localised site.", refs: ["keynote-170", "pembrolizumab", "nivolumab", "brentuximab-vedotin", "axicabtagene-ciloleucel", "lisocabtagene-maraleucel", "car-t", "autologous-stem-cell-transplant", "lymphoma-tx-car-t-pathway", "lymphoma-tx-radiotherapy"], guideline: { version: "NCCN B-Cell Lymphomas; KEYNOTE-170", url: SRC.nciPdqNhl } },
  ],

  // ------------------------------------------------------------------ BURKITT LYMPHOMA
  burkitt: [
    { setting: "Burkitt lymphoma in adults: which intensive regimen, and the pre-phase that prevents tumour lysis", approach: "The fastest-growing human tumour, with a doubling time measured in hours, and curable in the large majority when treated immediately with an intensive multi-agent regimen that includes central nervous system-directed treatment. R-CHOP is not adequate and should not be used.\n\nThree accepted regimens. Risk-adapted dose-adjusted EPOCH-R, tested in 113 adults across 22 centres: low-risk patients received three cycles with no central nervous system prophylaxis and high-risk patients six cycles with intrathecal prophylaxis; event-free survival was 84.5 per cent and overall survival 87.0 per cent at a median 58.7 months, with event-free survival of 100 per cent in the low-risk group and 82.1 per cent in the high-risk group. It worked equally well regardless of age, HIV status and IPI group, and five patients (4 per cent) died of treatment. CODOX-M/IVAC and hyper-CVAD with high-dose methotrexate and cytarabine are the older, more intensive inpatient alternatives, used particularly where there is central nervous system involvement, for which dose-adjusted EPOCH-R performed least well.\n\nBefore the first full dose: a pre-phase of low-dose cyclophosphamide and prednisolone for about a week to shrink the tumour gradually, intravenous fluids, allopurinol or rasburicase, and electrolyte monitoring every six to eight hours. Tumour lysis syndrome, not the lymphoma, is what kills people in the first week.", refs: ["lymphoma-tx-tumour-lysis", "rasburicase", "lymphoma-tx-regimen-alphabet", "rituximab", "etoposide", "doxorubicin", "cyclophosphamide", "vincristine", "prednisone", "methotrexate", "cytarabine", "ifosfamide", "intrathecal-therapy", "lymphoma-tx-fertility-preservation"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO; risk-adapted DA-EPOCH-R (JCO 2020)", url: SRC.burkittEpochR } },
    { setting: "Burkitt lymphoma with HIV, and in countries where the endemic form is common", approach: "HIV does not change the regimen. In the 113-adult dose-adjusted EPOCH-R study a quarter of patients were HIV positive and did as well as the rest; antiretroviral therapy is continued through chemotherapy, with attention to interactions, and co-trimoxazole prophylaxis is given. Rituximab is used in HIV-associated Burkitt lymphoma provided the CD4 count is not very low.\n\nThe endemic form, driven by Epstein-Barr virus and malaria and presenting as a jaw or abdominal mass in children in equatorial Africa, is treated with regimens designed for what a unit can actually deliver: reduced-intensity cyclophosphamide-based protocols with intrathecal therapy, given where blood products, dialysis and intensive care may not be available. Cure rates in those settings are lower than in high-income countries, and the limiting factors are late presentation, abandonment of treatment and supportive care rather than the drugs. Where rituximab can be obtained, adding it to chemotherapy improves outcomes in high-risk paediatric mature B-cell lymphoma.", refs: ["paper-hesseling-pediatr-blood-cancer", "paper-minard-colin-n-engl-j-med", "paper-sparano-blood", "rituximab", "cyclophosphamide", "intrathecal-therapy", "ebv-term", "lymphoma-tx-tumour-lysis", "lymphoma-tx-pjp-and-infection-prophylaxis"], guideline: { version: "NCI PDQ childhood non-Hodgkin lymphoma; Hesseling et al. for resource-limited settings", url: SRC.nciPdqChildNhl } },
    { setting: "Burkitt lymphoma that relapses", approach: "Relapse is uncommon, occurs early and is difficult to treat; it is the reason the first regimen must be the right one. Options are a non-cross-resistant salvage regimen such as R-ICE or R-GDP followed by autologous or allogeneic transplant in those who respond, CD19 CAR-T, which has activity but is less well established here than in diffuse large B-cell lymphoma, and a clinical trial. Central nervous system involvement at relapse requires high-dose methotrexate or cytarabine with intrathecal therapy. Early and explicit discussion of what is realistic belongs in this conversation, alongside the offer of a trial.", refs: ["lymphoma-tx-regimen-alphabet", "lymphoma-tx-transplant-role", "autologous-stem-cell-transplant", "allogeneic-hsct", "car-t", "axicabtagene-ciloleucel", "methotrexate", "cytarabine", "palliative-care"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO", url: SRC.nciPdqNhl } },
  ],

  // ------------------------------------------------------------------ PRIMARY CNS LYMPHOMA
  pcnsl: [
    { setting: "Primary CNS lymphoma: why R-CHOP fails, and what is given instead", approach: "A diffuse large B-cell lymphoma confined to the brain, spinal cord, eyes or meninges. The drugs that cure it elsewhere do not reach it: cyclophosphamide, doxorubicin and vincristine cross the blood-brain barrier poorly, so R-CHOP produces responses in the body and not in the brain, and trials of it in this disease were abandoned decades ago. Surgery has no therapeutic role beyond biopsy, and debulking does not help. Corticosteroids shrink the tumour dramatically and dissolve the diagnostic material with it, so steroids are withheld until the biopsy is taken wherever the patient is stable enough to wait.\n\nInduction is built around high-dose methotrexate at 3 to 3.5 g per square metre or more, given with leucovorin rescue and urinary alkalinisation, every two to three weeks. MATRix adds cytarabine, thiotepa and rituximab: in the first randomisation of IELSG32 the complete remission rate was 49 per cent with MATRix against 23 per cent with methotrexate and cytarabine alone and 30 per cent with methotrexate, cytarabine and rituximab. Six per cent of patients died of toxicity, so it is for patients fit enough to take it. The contribution of rituximab itself is contested: HOVON 105 randomised it into a methotrexate-based regimen and did not show the benefit that IELSG32's arm B against arm A comparison suggested.", refs: ["methotrexate", "cytarabine", "thiotepa", "rituximab", "cns-penetration", "lymphoma-tx-regimen-alphabet", "intrathecal-therapy", "paper-ferreri-leukemia"], guideline: { version: "NCCN Central Nervous System Cancers; ESMO/EANO; IELSG32, HOVON 105", url: SRC.nciPdqCns } },
    { setting: "Consolidation after methotrexate-based induction: transplant against whole-brain radiotherapy", approach: "Induction alone relapses, so responders are consolidated. The two options are thiotepa-based high-dose chemotherapy with an autologous stem cell transplant, or whole-brain radiotherapy, and the choice is dominated by what each does to thinking.\n\nMATRix/IELSG43 randomised consolidation in the largest trial ever run in this disease: three-year progression-free survival was 78 per cent (95 per cent confidence interval 69 to 85) with transplant against 51 per cent (41 to 60) with non-myeloablative R-DeVIC consolidation, hazard ratio 0.43, with overall survival also improved; the cost was more toxicity, a mean of 14.6 against 9.3 adverse events per patient and five against two fatal serious adverse events. In the earlier IELSG32 trial, whole-brain radiotherapy and autologous transplant were similarly effective, and at seven years the difference was cognitive: patients who had whole-brain radiotherapy lost attention and executive function, while those who had transplant improved in those domains, in memory and in quality of life. Seven-year overall survival was 21, 37 and 56 per cent for the three induction arms, and 70 per cent for patients who received MATRix and went on to consolidation.\n\nSo transplant is preferred for patients fit enough. Whole-brain radiotherapy is reserved for those who are not, usually at a reduced dose, and is increasingly deferred to relapse.", refs: ["paper-matrix-ielsg43-asct-consolidation-pcnsl-illerhaus-lancet-2026", "paper-ferreri-leukemia", "autologous-stem-cell-transplant", "thiotepa", "carmustine", "busulfan", "lymphoma-tx-transplant-role", "lymphoma-tx-radiotherapy", "late-effects"], guideline: { version: "NCCN Central Nervous System Cancers; IELSG32 and IELSG43", url: SRC.ielsg32Long } },
    { setting: "Primary CNS lymphoma in older or less fit patients, and at relapse", approach: "Age is not by itself a reason to withhold methotrexate: reduced-intensity methotrexate-based combinations, usually with rituximab and an alkylating agent such as procarbazine or temozolomide, are given to patients in their seventies and eighties with attention to renal function, and produce durable remissions in a minority. Whole-brain radiotherapy in older patients carries a high risk of progressive cognitive decline and is generally avoided as first consolidation.\n\nAt relapse the options depend on the interval. Re-treatment with methotrexate is effective in patients who relapse late, and in the seven-year IELSG32 report it was the only salvage that clearly benefited anyone. Other options are high-dose cytarabine with thiotepa and transplant if not already given, whole-brain radiotherapy if not already given, ibrutinib, which crosses into the brain and has single-agent activity, lenalidomide with rituximab, temozolomide, and a clinical trial. Ocular involvement is treated with systemic therapy, often with intravitreal methotrexate or rituximab added.", refs: ["methotrexate", "rituximab", "procarbazine", "temozolomide", "ibrutinib", "lenalidomide", "cytarabine", "thiotepa", "cns-penetration", "lymphoma-tx-transplant-role", "palliative-care"], guideline: { version: "NCCN Central Nervous System Cancers; IELSG32 seven-year report", url: SRC.ielsg32Long } },
  ],

  // ------------------------------------------------------------------ FOLLICULAR LYMPHOMA
  fl: [
    { setting: "Stage I and contiguous stage II follicular lymphoma: radiotherapy with curative intent", approach: "Truly localised follicular lymphoma, which means stage I or contiguous stage II confirmed on PET-CT and marrow assessment, is treated with 24 Gy in 12 fractions to an involved-site field and a substantial minority never relapse. PET staging matters: a quarter or more of patients thought to have stage I on CT are upstaged, and those are the ones who relapse outside the field.\n\nAdding systemic treatment lengthens remission without proven survival gain. TROG 99.03 randomised 150 patients after 30 Gy involved-field radiotherapy to observation or six cycles of CVP, with rituximab added from 2006: ten-year progression-free survival was 59 per cent with systemic therapy against 41 per cent with radiotherapy alone (hazard ratio 0.57), overall survival was not significantly different (95 against 87 per cent), and the effect was largest in the rituximab-containing subgroup. Four gray in two fractions is not an alternative for cure: FoRT found it clearly inferior to 24 Gy for local control.\n\nObservation is a defensible option in an older patient with a small, asymptomatic node, and so is rituximab alone. Doing nothing is not the same as doing nothing wrong.", refs: ["paper-fort-4gy-vs-24gy-indolent-lymphoma-hoskin-lancet-oncol-2014", "lymphoma-tx-radiotherapy", "imrt-igrt", "fdg-pet", "rituximab", "cyclophosphamide", "vincristine", "prednisone", "lymphoma-tx-watch-and-wait", "flipi"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO; TROG 99.03, FoRT", url: SRC.trog9903 } },
    { setting: "Advanced follicular lymphoma with no symptoms: watch and wait, or rituximab alone", approach: "Starting chemotherapy early does not lengthen life in asymptomatic, low-burden disease, and a third of people never need treatment in the first few years. The British-led trial that settled this randomised 379 patients with asymptomatic, non-bulky, advanced disease: at three years, 46 per cent of those watched had not needed treatment against 88 per cent of those given four weekly doses of rituximab and two years of maintenance (hazard ratio 0.21), with no overall survival difference. So rituximab delays the next treatment; it does not extend life, and it costs two years of visits.\n\nThe GELF criteria are the usual trigger to treat: a mass of 7 cm or more, three or more nodal sites each 3 cm or more, B symptoms, splenomegaly, effusion, cytopenias or a leukaemic phase. Monitoring is clinic review and bloods every three to six months; routine scanning of a well person finds little.", refs: ["lymphoma-tx-watch-and-wait", "watchful-waiting", "rituximab", "flipi", "lymphoma-tx-maintenance"], guideline: { nccn: "Category 1 (observation for low tumour burden)", version: "NCCN B-Cell Lymphomas; ESMO; Ardeshna 2014", url: SRC.ardeshnaWatchWait } },
    { setting: "Advanced follicular lymphoma needing treatment: which induction, and whether to add maintenance", approach: "Chemoimmunotherapy is the usual first treatment, and the choice of chemotherapy backbone is made on toxicity. Bendamustine with rituximab gave median progression-free survival of 69.5 against 31.2 months for R-CHOP in the StiL NHL1 trial of indolent and mantle cell lymphoma (hazard ratio 0.58), with no alopecia, less haematological toxicity, fewer infections and far less neuropathy, and is the commonest first choice; it does deplete T cells for a long time, which matters for anyone who may need CAR-T later. R-CHOP is preferred where transformation is suspected. R-CVP is the gentlest.\n\nObinutuzumab instead of rituximab improves progression-free survival: GALLIUM randomised 1,401 patients and gave three-year progression-free survival of 80.0 against 73.3 per cent (hazard ratio 0.66), at the cost of more grade 3 to 5 adverse events (74.6 against 67.8 per cent) and more infusion reactions.\n\nChemotherapy-free induction is a real alternative. RELEVANCE randomised 1,030 patients to rituximab with lenalidomide or rituximab with the investigator's chemotherapy: complete response at 120 weeks was 48 against 53 per cent and median progression-free survival 120.2 against 123.8 months (hazard ratio 0.92), so R-squared is not superior but is equivalent, with less neutropenia (32 against 50 per cent) and more rash.\n\nMaintenance rituximab for two years afterwards lengthens remission substantially and does not lengthen life: in PRIMA median progression-free survival was 10.5 against 4.1 years but ten-year overall survival was about 80 per cent in both arms. It is a choice, not a requirement.", refs: ["gallium", "relevance", "obinutuzumab", "rituximab", "bendamustine", "lenalidomide", "r-chop", "cyclophosphamide", "vincristine", "prednisone", "lymphoma-tx-maintenance", "paper-rummel-lancet", "paper-gallium-obinutuzumab-first-line-follicular-lymphoma-marcus-nejm-2017", "paper-relevance-rituximab-lenalidomide-follicular-lymphoma-morschhauser-nejm-2018"], guideline: { nccn: "Category 1", version: "NCCN B-Cell Lymphomas; ESMO; GALLIUM, RELEVANCE, StiL NHL1, PRIMA", url: SRC.prima2019 } },
    { setting: "Progression within two years of first chemotherapy (POD24): biopsy first, then a different class of treatment", approach: "About one in five people treated with first-line chemoimmunotherapy progress within two years, and their five-year overall survival in the National LymphoCare Study was 50 per cent against 90 per cent for everyone else, a difference that held after adjusting for FLIPI.\n\nThe first step is a repeat biopsy, because transformation to diffuse large B-cell lymphoma is the commonest explanation and is treated as aggressive lymphoma. If it is still follicular, the plan changes class rather than repeating it: CD19 CAR-T (ZUMA-5 reported an overall response of 92 per cent and complete response 74 per cent; ELARA with tisagenlecleucel reported complete response 69.1 per cent and overall response 86.2 per cent), a CD20 bispecific antibody, or lenalidomide with rituximab. A clinical trial is a reasonable first choice at this point. Autologous transplant still has a role in younger patients with chemosensitive early relapse and is used less than it was.", refs: ["lymphoma-tx-pod24", "zuma-5", "axicabtagene-ciloleucel", "tisagenlecleucel", "mosunetuzumab", "odronextamab", "epcoritamab", "lenalidomide", "rituximab", "car-t", "lymphoma-tx-car-t-pathway", "autologous-stem-cell-transplant", "flipi"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO; ZUMA-5, ELARA", url: SRC.elara } },
    { setting: "Relapsed follicular lymphoma after two or more lines: bispecific antibodies, CAR-T and R-squared", approach: "Nothing here is curative and all of it can produce long remissions, so the choice is about duration of treatment, side effects and how far a person is willing to travel.\n\nFixed-duration bispecific antibodies. Mosunetuzumab, given intravenously in 21-day cycles with step-up dosing and stopped after eight cycles in complete responders, produced a complete response in 60.0 per cent of 90 patients after two or more lines. Odronextamab in ELM-2 gave an objective response of 80.0 per cent, complete response 73.4 per cent and median progression-free survival 20.7 months in 128 patients, with grade 3 or worse cytokine release syndrome of 1.7 per cent using the split step-up. Epcoritamab is approved in combination with rituximab and lenalidomide.\n\nCAR-T. Axicabtagene ciloleucel (ZUMA-5) and tisagenlecleucel (ELARA) both produce high complete response rates with remissions that are lasting in a substantial minority; the trade is a single intensive episode against repeated outpatient treatment.\n\nRituximab with lenalidomide. AUGMENT randomised 358 patients with relapsed follicular or marginal zone lymphoma to lenalidomide with rituximab or rituximab with placebo: median progression-free survival 39.4 against 14.1 months (hazard ratio 0.46), with grade 3 to 4 neutropenia in 50 against 13 per cent.\n\nAntibody and inhibitor combinations approved since 2024. Tafasitamab with lenalidomide and rituximab received traditional United States approval on 18 June 2025 on the inMIND trial, with a label note that it is not indicated in relapsed or refractory marginal zone lymphoma outside a trial. Zanubrutinib with obinutuzumab was given accelerated approval on 7 March 2024 on ROSEWOOD. Lisocabtagene maraleucel's follicular approval of 15 May 2024 converted to traditional approval on 20 February 2026, and a separate marginal zone lymphoma approval followed on 4 December 2025.\n\nOther options: a different chemoimmunotherapy backbone from the one used before, obinutuzumab with bendamustine in rituximab-refractory disease, tazemetostat for EZH2-mutant disease or where nothing else is suitable, radiotherapy to a single symptomatic site, and radioimmunotherapy where it is still available. The PI3K inhibitors (idelalisib, duvelisib, copanlisib) have largely been withdrawn from this indication on the basis of toxicity and unconfirmed benefit.", refs: ["augment", "zuma-5", "mosunetuzumab", "odronextamab", "epcoritamab", "lenalidomide", "rituximab", "obinutuzumab", "bendamustine", "tazemetostat", "axicabtagene-ciloleucel", "tisagenlecleucel", "lisocabtagene-maraleucel", "tafasitamab", "zanubrutinib", "radioimmunotherapy", "lymphoma-tx-bispecific-step-up", "lymphoma-tx-radiotherapy", "paper-augment-lenalidomide-rituximab-leonard-jco-2019"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO; AUGMENT, ELM-2, mosunetuzumab phase 2", url: SRC.elm2Follicular } },
    { setting: "Transformation of follicular lymphoma to diffuse large B-cell lymphoma", approach: "Suspected when a single site grows quickly, LDH rises, B symptoms appear or the PET shows one site far brighter than the rest; confirmed by biopsy of that site, which is why a repeat biopsy rather than a scan is the right first step. It occurs in roughly 2 to 3 per cent of patients a year.\n\nTreatment follows the aggressive lymphoma pathway, not the follicular one. In a patient who has had little or no previous chemotherapy, R-CHOP or pola-R-CHP with the intent to cure, often followed by consideration of autologous transplant consolidation. In a patient who has already had several lines, CD19 CAR-T; transformed disease was included in the pivotal CAR-T populations. Bispecific antibodies are active. The outlook is better than it was when transformation was treated with more of the same.", refs: ["r-chop", "polarix", "polatuzumab-vedotin", "rituximab", "axicabtagene-ciloleucel", "lisocabtagene-maraleucel", "glofitamab", "epcoritamab", "autologous-stem-cell-transplant", "fdg-pet", "lymphoma-tx-car-t-pathway", "lymphoma-tx-pod24"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO", url: SRC.nciPdqNhl } },
  ],

  // ------------------------------------------------------------------ MARGINAL ZONE (HUB)
  mzl: [
    { setting: "Marginal zone lymphoma: three different diseases under one name", approach: "Extranodal marginal zone lymphoma of mucosa-associated lymphoid tissue (MALT) arises at a site of chronic inflammation, most often the stomach, and is the one that can sometimes be cured with antibiotics. Splenic marginal zone lymphoma presents with a large spleen, cytopenias and circulating villous lymphocytes, and is associated with hepatitis C. Nodal marginal zone lymphoma behaves much like follicular lymphoma and is treated like it. The three share a cell of origin and very little else in the way of treatment, so the first question is which one it is.\n\nTwo tests change the plan at diagnosis. Helicobacter pylori status in gastric MALT, because eradication is the first treatment. Hepatitis C status in splenic and nodal disease, because antiviral treatment alone can produce lymphoma remission in hepatitis C-associated cases. Other site-specific associations are recorded and occasionally actionable: Chlamydia psittaci in ocular adnexal MALT, Borrelia burgdorferi in cutaneous MALT, Campylobacter jejuni in immunoproliferative small intestinal disease.", refs: ["paper-esmo-marginal-zone-lymphoma-zucca-ann-oncol-2020", "lymphoma-tx-h-pylori-eradication", "lymphoma-tx-watch-and-wait", "rituximab"], guideline: { version: "ESMO marginal zone lymphomas (Zucca et al.); NCCN B-Cell Lymphomas", url: SRC.esmoHaem } },
    { setting: "Marginal zone lymphoma that is advanced, symptomatic or has relapsed", approach: "Treatment is indicated for symptoms, organ compromise, cytopenias or rapid progression, not for the presence of disease. Rituximab alone produces responses in about half. Chemoimmunotherapy with bendamustine and rituximab is the usual choice when more is needed, and rituximab with chlorambucil has the only randomised evidence in MALT (IELSG-19: five-year event-free survival 68 per cent for the combination against 51 per cent for chlorambucil and 50 per cent for rituximab alone, with five-year overall survival about 90 per cent in each arm, so the combination delays events without changing survival).\n\nAt relapse, the BTK inhibitors are the newest class: MAGNOLIA treated relapsed or refractory marginal zone lymphoma of all subtypes with zanubrutinib and reported an objective response of 68 per cent, complete response 26 per cent and 15-month progression-free survival of 83 per cent, with fewer cardiac events than ibrutinib. Lenalidomide with rituximab is an option and marginal zone patients were included in AUGMENT. Lisocabtagene maraleucel received United States approval for relapsed or refractory marginal zone lymphoma after two or more prior lines on 4 December 2025. Local radiotherapy at 24 Gy remains the right answer for a single symptomatic site whatever the line.", refs: ["rituximab", "bendamustine", "chlorambucil", "zanubrutinib", "ibrutinib", "lenalidomide", "lisocabtagene-maraleucel", "augment", "lymphoma-tx-radiotherapy", "paper-magnolia-zanubrutinib-mzl-ccr-2021", "paper-esmo-marginal-zone-lymphoma-zucca-ann-oncol-2020"], guideline: { version: "ESMO marginal zone lymphomas; NCCN B-Cell Lymphomas; IELSG-19, MAGNOLIA", url: SRC.ielsg19 } },
  ],

  // ------------------------------------------------------------------ MALT
  malt: [
    { setting: "Gastric MALT lymphoma: a cancer cured by antibiotics", approach: "Helicobacter pylori eradication is the first treatment for every Helicobacter-positive gastric MALT lymphoma, whatever the stage, and it is a cure in most of them. The observation that made this possible was published in 1993, when eradication produced regression of the lymphoma in five of six patients, and it remains one of the very few instances in oncology in which a course of antibiotics is the definitive treatment of a malignancy.\n\nWhat is given: a standard triple or quadruple eradication regimen chosen by local resistance patterns, typically a proton pump inhibitor with two antibiotics for 10 to 14 days. Eradication is then confirmed, by urea breath test or stool antigen at least four weeks after antibiotics and two weeks off the proton pump inhibitor, because failure of eradication is the commonest reason for failure of the lymphoma to respond.\n\nWhat happens next: endoscopic and histological follow-up every three to six months. Regression is slow and can take twelve to eighteen months, so persistent histological disease in a patient whose Helicobacter has been eradicated and who has no symptoms is watched, not treated. The t(11;18) translocation predicts failure to respond to eradication and is worth testing where it is available. Helicobacter-negative gastric MALT lymphoma is still given eradication therapy in many centres, because some respond, but it is not relied on.", refs: ["paper-wotherspoon-h-pylori-malt-lancet-1993", "lymphoma-tx-h-pylori-eradication", "lymphoma-tx-watch-and-wait", "endoscopy", "paper-esmo-marginal-zone-lymphoma-zucca-ann-oncol-2020"], guideline: { nccn: "Category 1 (Helicobacter eradication, Helicobacter-positive gastric MALT)", version: "ESMO marginal zone lymphomas; NCCN B-Cell Lymphomas", url: SRC.esmoHaem } },
    { setting: "Gastric MALT lymphoma that does not respond to eradication, and MALT at other sites", approach: "Where the Helicobacter has been eradicated and the lymphoma persists and is causing symptoms or progressing, radiotherapy is the next treatment: about 24 Gy in 12 fractions to the stomach, which controls the disease in the great majority. Systemic treatment, usually rituximab alone or rituximab with chlorambucil or bendamustine, is used for disseminated disease or where radiotherapy is not possible. Surgery has no routine role.\n\nMALT lymphoma at other sites, salivary gland, thyroid, lung, skin, orbit, breast, is treated on the same principle: a localised, symptomatic site gets 24 Gy, an asymptomatic one can be watched, and disseminated disease gets rituximab-based systemic treatment. Ocular adnexal MALT is sometimes given doxycycline first for Chlamydia psittaci, with response rates that vary widely by region. Salivary gland MALT in Sjogren syndrome and thyroid MALT in Hashimoto thyroiditis are managed jointly with the specialty that treats the underlying autoimmune disease.\n\nThe IELSG-19 trial is the randomised evidence for systemic treatment: five-year event-free survival was 68 per cent with chlorambucil and rituximab, 51 per cent with chlorambucil alone and 50 per cent with rituximab alone, with five-year overall survival of about 90 per cent in each arm.", refs: ["lymphoma-tx-radiotherapy", "rituximab", "chlorambucil", "bendamustine", "imrt-igrt", "paper-esmo-marginal-zone-lymphoma-zucca-ann-oncol-2020"], guideline: { version: "ESMO marginal zone lymphomas; NCCN B-Cell Lymphomas; IELSG-19", url: SRC.ielsg19 } },
  ],

  // ------------------------------------------------------------------ SPLENIC MARGINAL ZONE
  smzl: [
    { setting: "Splenic marginal zone lymphoma: hepatitis C first, then rituximab, then splenectomy", approach: "An indolent disease of the spleen, marrow and blood. A patient with no symptoms, no cytopenias and a spleen that is not troublesome is watched, sometimes for years.\n\nWhen treatment is needed, the order is: test and treat hepatitis C if present, because direct-acting antivirals alone produce lymphoma remission in a proportion of hepatitis C-associated cases and that is a reason to check before giving any chemotherapy. Then rituximab alone, weekly for four to eight doses, which corrects cytopenias and shrinks the spleen in the large majority and has displaced splenectomy as first treatment. Chemoimmunotherapy with bendamustine and rituximab is used for disease that does not respond or that transforms.\n\nSplenectomy is now reserved for patients who cannot have rituximab, whose disease is confined to the spleen and who need a diagnosis, or who have refractory painful splenomegaly. It requires pneumococcal, Haemophilus influenzae type b and meningococcal vaccination at least two weeks beforehand where possible, and lifelong penicillin prophylaxis afterwards. Zanubrutinib has activity in relapsed disease across marginal zone subtypes.", refs: ["rituximab", "bendamustine", "zanubrutinib", "lymphoma-tx-watch-and-wait", "lymphoma-tx-pjp-and-infection-prophylaxis", "paper-magnolia-zanubrutinib-mzl-ccr-2021", "paper-esmo-marginal-zone-lymphoma-zucca-ann-oncol-2020"], guideline: { version: "ESMO marginal zone lymphomas; NCCN B-Cell Lymphomas", url: SRC.esmoHaem } },
  ],

  // ------------------------------------------------------------------ NODAL MARGINAL ZONE
  nmzl: [
    { setting: "Nodal marginal zone lymphoma: treated like follicular lymphoma, with the same choices", approach: "Nodal marginal zone lymphoma has no site-specific treatment of its own and is managed on the follicular lymphoma pathway: watch and wait while asymptomatic, involved-site radiotherapy at 24 Gy for genuinely localised disease, and rituximab-based chemoimmunotherapy (bendamustine and rituximab, or R-CVP) when the disease causes symptoms, organ compromise or cytopenias. Lenalidomide with rituximab is supported by AUGMENT, which enrolled marginal zone as well as follicular lymphoma and gave median progression-free survival of 39.4 against 14.1 months for rituximab alone. Zanubrutinib is an option at relapse on the strength of MAGNOLIA. Hepatitis C should be tested for, as in the splenic form. Transformation to diffuse large B-cell lymphoma is treated as aggressive lymphoma.", refs: ["rituximab", "bendamustine", "lenalidomide", "zanubrutinib", "augment", "lymphoma-tx-watch-and-wait", "lymphoma-tx-radiotherapy", "paper-magnolia-zanubrutinib-mzl-ccr-2021"], guideline: { version: "ESMO marginal zone lymphomas; NCCN B-Cell Lymphomas; AUGMENT, MAGNOLIA", url: SRC.esmoHaem } },
  ],

  // ------------------------------------------------------------------ MANTLE CELL
  mcl: [
    { setting: "Mantle cell lymphoma: the three things to establish before choosing treatment", approach: "Mantle cell lymphoma is not one disease. Classical nodal disease behaves aggressively and needs treatment. Leukaemic non-nodal mantle cell lymphoma, with SOX11-negative, hypermutated immunoglobulin genes, splenomegaly and circulating cells but no lymphadenopathy, can be watched for years, and treating it early does harm without benefit. Blastoid and pleomorphic variants behave much more aggressively.\n\nThree things to establish. First, the growth pattern and Ki-67 index: above about 30 per cent signals aggressive disease. Second, TP53 mutation status, which is the single strongest adverse factor and predicts poor response to intensive chemotherapy and to autologous transplant; a TP53-mutated patient is a candidate for a novel-agent regimen or a trial rather than for intensification. Third, the MIPI score, which combines age, performance status, LDH and white cell count. Gastrointestinal involvement is near-universal at a microscopic level and colonoscopy is not required in every patient.", refs: ["mipi", "lymphoma-tx-watch-and-wait", "lymphoma-tx-regimen-alphabet", "fdg-pet"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO; BSH", url: SRC.nciPdqNhl } },
    { setting: "First-line mantle cell lymphoma in younger, fitter patients after TRIANGLE: ibrutinib in, transplant optional", approach: "TRIANGLE randomised 870 patients up to 65 who were fit for transplant to three arms: alternating R-CHOP and R-DHAP induction with autologous transplant (arm A); the same with ibrutinib added to induction and as two-year maintenance (arm A+I); or ibrutinib-containing induction and maintenance without transplant (arm I). Three-year failure-free survival was 88 per cent for arm A+I against 72 per cent for arm A (hazard ratio 0.52). Transplant was not shown to be superior to the ibrutinib-containing regimen without it: 72 per cent for arm A against 86 per cent for arm I. Adding ibrutinib to transplant increased grade 3 to 5 haematological events during maintenance and follow-up (50 per cent in arm A+I against 21 per cent in arm A) and infections (25 against 13 per cent).\n\nWhat changed in practice: a covalent BTK inhibitor belongs in first-line treatment of younger patients, and autologous transplant is no longer automatic. Many units now give ibrutinib-containing induction and maintenance without transplant, particularly in TP53-mutated disease where transplant has never worked well. Where transplant is used, rituximab maintenance afterwards improves survival: LyMa randomised 240 patients after transplant to three years of rituximab or observation and found four-year event-free survival of 79 against 61 per cent, with overall survival also improved.\n\nCytarabine-containing induction (R-DHAP or the Nordic regimen) remains the backbone where an intensive approach is chosen. In England, NICE TA1193 allows exactly the TRIANGLE schedule: ibrutinib with R-CHOP alternating with R-DHAP or R-DHAOx, followed by ibrutinib alone, for untreated disease in adults for whom an autologous transplant is suitable.", refs: ["triangle", "ibrutinib", "rituximab", "cytarabine", "cisplatin", "dexamethasone", "oxaliplatin", "r-chop", "autologous-stem-cell-transplant", "lymphoma-tx-transplant-role", "lymphoma-tx-maintenance", "lymphoma-tx-uk-access", "mipi", "paper-triangle-ibrutinib-mantle-cell-lymphoma-dreyling-lancet-2024"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO; TRIANGLE, LyMa", url: SRC.lyma } },
    { setting: "First-line mantle cell lymphoma in older patients: the British answer and the international one", approach: "Two randomised trials, two different regimens, and a real difference between British and American practice.\n\nENRICH, run at 66 sites in the United Kingdom and the Nordic countries, randomised 397 patients aged 60 and over to ibrutinib with rituximab or to the investigator's choice of immunochemotherapy (R-CHOP or bendamustine-rituximab), both followed by two years of rituximab maintenance, with ibrutinib continued until progression. At a median follow-up of 47.9 months the adjusted hazard ratio for progression-free survival was 0.69 in favour of ibrutinib-rituximab. The benefit was concentrated where the comparator was R-CHOP (hazard ratio 0.37) and was not demonstrated against bendamustine-rituximab (0.91). Grade 3 or worse adverse events were similar (67 against 70 per cent). This is the first randomised trial in untreated mantle cell lymphoma to show a chemotherapy-free combination beating immunochemotherapy, and it is British practice.\n\nSHINE took the other route and added ibrutinib to bendamustine-rituximab in 523 patients aged 65 and over: median progression-free survival 80.6 against 52.9 months (hazard ratio 0.75) with no overall survival difference and grade 3 or 4 adverse events in 81.5 against 77.3 per cent.\n\nSo: ibrutinib-rituximab without chemotherapy for a patient in whom bendamustine is unattractive, and bendamustine-rituximab with or without a BTK inhibitor otherwise. Acalabrutinib and zanubrutinib are the second-generation covalent BTK inhibitors, with less atrial fibrillation and hypertension than ibrutinib, and are substituted in patients with cardiac risk. Acalabrutinib with bendamustine and rituximab received traditional United States approval on 16 January 2025 on the ECHO trial for untreated mantle cell lymphoma in people not eligible for an autologous transplant, and NICE TA1184 recommends the same combination in England for the same group. VR-CAP, which replaces vincristine with bortezomib, is an alternative backbone.", refs: ["ibrutinib", "rituximab", "bendamustine", "acalabrutinib", "zanubrutinib", "bortezomib", "r-chop", "lymphoma-tx-uk-versus-us", "lymphoma-tx-maintenance", "lymphoma-tx-regimen-alphabet"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO; ENRICH, SHINE", url: SRC.enrich } },
    { setting: "Relapsed mantle cell lymphoma that has not yet had a BTK inhibitor", approach: "A covalent BTK inhibitor is the standard next treatment and produces responses in about two thirds. Acalabrutinib and zanubrutinib are preferred over ibrutinib on cardiovascular toxicity where both are available. Adding venetoclax lengthens remission: SYMPATICO randomised 366 patients after one to five prior lines to ibrutinib with venetoclax or ibrutinib with placebo and gave median progression-free survival of 31.9 against 22.1 months (hazard ratio 0.629), with a complete response of 69.2 per cent in a separate open-label arm of treatment-naive TP53-mutated disease. Venetoclax carries a tumour lysis risk that requires a ramp-up and monitoring.\n\nOther options at this point are lenalidomide with rituximab, bortezomib-containing regimens, bendamustine with rituximab if not used before, and a clinical trial. Autologous transplant is rarely useful at relapse; allogeneic transplant is reserved for young, fit patients with chemosensitive disease.", refs: ["sympatico", "ibrutinib", "acalabrutinib", "zanubrutinib", "venetoclax", "lenalidomide", "rituximab", "bortezomib", "bendamustine", "lymphoma-tx-tumour-lysis", "allogeneic-hsct"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO; SYMPATICO", url: SRC.nciPdqNhl } },
    { setting: "Mantle cell lymphoma after a BTK inhibitor has failed: brexucabtagene autoleucel and pirtobrutinib", approach: "Progression on a covalent BTK inhibitor was, until 2020, the point at which there was little left. Two treatments changed it.\n\nBrexucabtagene autoleucel, a CD19 CAR-T product, was tested in ZUMA-2 in 105 patients who had all had a BTK inhibitor: objective response 93 per cent and complete response 67 per cent in the primary efficacy analysis, 85 per cent by intention to treat, with progression-free survival of 61 per cent and overall survival of 83 per cent at twelve months. The toxicity is real: grade 3 or higher cytokine release syndrome in 15 per cent and grade 3 or higher neurological events in 31 per cent, higher than the CD19 products used in large B-cell lymphoma. Referral should happen as the BTK inhibitor starts to fail, not after the next line, because apheresis quality falls with further treatment.\n\nPirtobrutinib, a non-covalent BTK inhibitor, works after covalent BTK inhibitor failure including in the presence of the C481S resistance mutation, and is an option for patients who are not candidates for CAR-T or who need disease control while a CAR-T product is manufactured.\n\nLisocabtagene maraleucel is the second CAR-T option, approved in the United States on 30 May 2024 for relapsed or refractory mantle cell lymphoma after at least two prior lines including a BTK inhibitor. Other options are venetoclax-based combinations, glofitamab with pirtobrutinib in a trial, allogeneic transplant in selected younger patients, and palliative radiotherapy to a symptomatic site. This is a point at which a trial is often the best available treatment.", refs: ["zuma-2", "brexucabtagene-autoleucel", "lisocabtagene-maraleucel", "pirtobrutinib", "venetoclax", "glofitamab", "car-t", "lymphoma-tx-car-t-pathway", "lymphoma-tx-crs-icans", "allogeneic-hsct", "palliative-radiotherapy", "paper-zuma-2-brexu-cel-mantle-cell-nejm-2020"], guideline: { version: "NCCN B-Cell Lymphomas; ESMO; ZUMA-2", url: SRC.nciPdqNhl } },
  ],

  // ------------------------------------------------------------------ WALDENSTROM
  wm: [
    { setting: "Waldenstrom macroglobulinaemia: what to test before treatment, and why the genotype matters", approach: "A lymphoplasmacytic lymphoma that secretes IgM. Two mutations, found by allele-specific PCR on a marrow aspirate, shape the whole plan. MYD88 L265P is present in more than 90 per cent and predicts response to BTK inhibitors; MYD88 wild-type disease responds much less well to them. CXCR4 mutations, present in about a third, predict slower and shallower responses to ibrutinib and a higher risk of a rise in IgM when treatment starts.\n\nTwo complications need to be looked for because they change the urgency. Hyperviscosity, from a very high IgM, causes headache, blurred vision, nosebleeds and confusion, is confirmed on fundoscopy, and is treated with plasma exchange before anything else. IgM-related peripheral neuropathy, often anti-MAG positive, is a reason to treat even when other criteria are not met, because nerve damage does not reverse.\n\nRituximab causes a transient rise in IgM, an IgM flare, in about half of patients, which can precipitate hyperviscosity; it is therefore held back or given after plasma exchange where the IgM is very high.", refs: ["paper-treon-blood", "rituximab", "ibrutinib", "zanubrutinib"], guideline: { version: "NCCN Waldenstrom Macroglobulinemia/Lymphoplasmacytic Lymphoma; ESMO; BSH", url: SRC.nciPdqNhl } },
    { setting: "Waldenstrom macroglobulinaemia, first treatment: BTK inhibitor or chemoimmunotherapy", approach: "Treatment is for symptoms, not for a number: anaemia, thrombocytopenia, constitutional symptoms, symptomatic organ or node enlargement, hyperviscosity, neuropathy, cryoglobulinaemia or amyloidosis. An asymptomatic patient is watched.\n\nTwo routes. Fixed-duration chemoimmunotherapy, usually bendamustine with rituximab for four to six cycles, gives deep responses and a treatment-free interval afterwards, and is the preference of many patients and many British units. Continuous BTK inhibition with zanubrutinib or ibrutinib gives high response rates without chemotherapy but is taken indefinitely.\n\nASPEN, the only head-to-head trial, randomised 201 patients with MYD88-mutated disease to zanubrutinib or ibrutinib: the complete or very good partial response rate by independent review was 28.4 against 19.2 per cent, which did not reach statistical significance, but zanubrutinib caused markedly less atrial fibrillation, hypertension, bleeding and diarrhoea. A separate cohort treated MYD88 wild-type disease with zanubrutinib. Where a BTK inhibitor is chosen, zanubrutinib is therefore preferred. Rituximab with cyclophosphamide and dexamethasone is an alternative chemoimmunotherapy for patients in whom bendamustine is unsuitable. Proteasome-inhibitor regimens containing bortezomib are used where a rapid response is needed and neuropathy is absent.", refs: ["aspen-wm", "zanubrutinib", "ibrutinib", "bendamustine", "rituximab", "cyclophosphamide", "dexamethasone", "bortezomib", "lymphoma-tx-watch-and-wait", "paper-tam-blood"], guideline: { version: "NCCN Waldenstrom Macroglobulinemia; ESMO; ASPEN", url: SRC.nciPdqNhl } },
    { setting: "Relapsed Waldenstrom macroglobulinaemia", approach: "The choice turns on what was used first and how long the remission lasted. After fixed-duration chemoimmunotherapy with a remission of two years or more, the same regimen can be repeated, or a BTK inhibitor started. After a BTK inhibitor, options are a different BTK inhibitor including the non-covalent pirtobrutinib, venetoclax, which has activity in this disease, proteasome-inhibitor regimens, chemoimmunotherapy if not previously used, and a clinical trial. Autologous transplant is occasionally used in younger patients with chemosensitive disease and multiple relapses. Transformation to diffuse large B-cell lymphoma is treated as aggressive lymphoma. Plasma exchange remains the immediate treatment for symptomatic hyperviscosity at any point.", refs: ["zanubrutinib", "ibrutinib", "pirtobrutinib", "venetoclax", "bortezomib", "bendamustine", "rituximab", "autologous-stem-cell-transplant", "lymphoma-tx-transplant-role"], guideline: { version: "NCCN Waldenstrom Macroglobulinemia; ESMO", url: SRC.nciPdqNhl } },
  ],
};

const mk = (cancerId: string, rows: NonNullable<CancerInput["standardOfCare"]>, extra: Spike["patch"] = {}): Spike => ({ cancerId, entities: [], patch: { standardOfCare: rows, ...extra } });

